INSERT INTO `locales_item` VALUES ('5528', '조리법: 조개 수프', 'Recette : Soupe de palourdes', 'Rezept: Muschelsuppe', '食谱：杂烩蚌肉', '食譜:蚌肉雜燴', 'Receta: sopa de almejas', 'Receta: sopa de almejas', 'Рецепт: похлебка из моллюсков', '조개 수프 요리하는 법을 배웁니다.', 'Vous apprend à préparer une délicieuse Soupe de palourdes.', 'Lehrt Euch, wie man eine köstliche Muschelsuppe zubereitet.', '教你学会烹制杂烩蚌肉。', '教你學會如何烹製蚌肉雜燴。', 'Te enseña a cocinar una deliciosa sopa de almejas.', 'Te enseña a cocinar una deliciosa sopa de almejas.', 'Обучает приготовлению похлебки из моллюсков.', '15050');
