INSERT INTO `locales_item` VALUES ('6339', '룬새김 은마법막대', 'Bâtonnet runique en argent', 'Runenverzierte Silberrute', '符文银棒', '符文銀棒', 'Vara rúnica de plata', 'Vara rúnica de plata', 'Рунический серебряный жезл', '낮은 등급의 마법막대로도 사용할 수 있습니다.', 'Peut remplacer tous les bâtonnets runiques d’enchantement inférieurs.', 'Kann auch wie jede geringere runenverzierte Rute verwendet werden.', '可代替任何较低等级的附魔棒。', '也可做為任何次等的符文附魔棒。', 'También puede servir de vara encantadora rúnica inferior.', 'También puede servir de vara encantadora rúnica inferior.', 'Может быть использован вместо любого из меньших рунических жезлов.', '15050');
