INSERT INTO `locales_item` VALUES ('13585', '추억의 유품', 'Livre du souvenir', 'Andenken der Erinnerung', '巫妖生前的遗物', '巫妖生前的遺物', 'Libro de los Recuerdos', 'Libro de los Recuerdos', 'Книга воспоминаний', '모든 페이지가 찢겨 나갔습니다.', 'Toutes les pages ont été déchirées.', 'Alle Seiten wurden herausgerissen.', '所有的书页都被撕破了。', '所有的書頁都被撕破了。', 'Todas las páginas están arrancadas.', 'Todas las páginas están arrancadas.', 'Все страницы вырваны.', '15050');
