INSERT INTO `locales_item` VALUES ('21770', '아옳옳옳옳옳의 반지', 'Anneau de Mmmrrrggglll', 'Mmmrrrgggllls Ring', '呜啦哇啦的戒指', '魔鉤的戒指', 'Anillo de Mmmrrrggglll', 'Anillo de Mmmrrrggglll', 'Кольцо Мррргла', '약간 녹슬어 있고 끈적거립니다.', 'Il est légèrement terni et visqueux.', 'Leicht angelaufen und schleimig.', '这枚戒指有点暗淡，而且粘糊糊的。', '看起來有些骯髒和污穢。', 'Está algo desgastado y resbaladizo.', 'Está algo desgastado y resbaladizo.', 'Оно слегка потускнело и немного липнет к пальцам.', '15050');
INSERT INTO `locales_item` VALUES ('21771', '선장 켈리센드라의 화물 상자', 'Cargaison du capitaine Kelisendra', 'Kapitänin Kelisendras Fracht', '凯莉森德拉船长的货物', '凱利山德拉船長的貨物', 'Cargamento de la capitana Kelisendra', 'Cargamento de la capitana Kelisendra', 'Груз капитана Келисендры', '겉이 좀 닳긴 했지만 안의 물건은 부서지지 않은 것 같습니다.', 'Elle a l\'air d\'avoir vécu, mais il semblerait que rien n\'ait été brisé à l\'intérieur.', 'Etwas verschlissener als zuvor, aber es hört sich nicht so an, als wäre darin etwas zerbrochen.', '箱子看起来有些糟糕，但是里面的货物应该没有受到损坏。', '外表看起來有點損壞，但裡面聽起來沒有東西破掉。', 'El aspecto es algo desgastado pero no parece haber nada roto en el interior.', 'El aspecto es algo desgastado pero no parece haber nada roto en el interior.', 'Упаковка слегка повреждена, но содержимое должно быть в порядке.', '15050');
INSERT INTO `locales_item` VALUES ('21774', '파괴의 에메랄드 왕관', 'Couronne d\'émeraude de destruction', 'Smaragdkrone der Zerstörung', '毁灭之翡翠王冠', '毀滅之翡翠王冠', 'Corona de esmeralda de destrucción', 'Corona de esmeralda de destrucción', 'Изумрудная корона разрушения', '', '', '', '', '', '', '', '', '15050');
