INSERT INTO `locales_item` VALUES ('21984', '군주 발타라크의 아뮬렛 왼쪽 조각', 'Morceau gauche de l\'amulette du seigneur Valthalak', 'Linkes Stück von Lord Valthalaks Amulett', '瓦塔拉克饰品的左半边', '瓦薩拉克領主護符的左半塊', 'Parte izquierda del amuleto de Lord Valthalak', 'Parte izquierda del amuleto de Lord Valthalak', 'Левая часть амулета Лорда Вальтхалака', '이 조각에 봉인된 악의 힘이 점점 강해지고 있는 것 같습니다...', 'Le mal piégé dans ce morceau semble devenir de plus en plus fort…', 'Das in diesem Stück gefangene Böse scheint stärker zu werden...', '被禁锢在里面的邪恶力量似乎在不断成长……', '惡魔被困在這個碎片裡好像越來越強大了……', 'El mal atrapado en su interior parece estar ganando fuerza...', 'El mal atrapado en su interior parece estar ganando fuerza...', 'Силы Зла, заключенные в этот фрагмент, кажется, растут.', '15050');
