INSERT INTO `locales_item` VALUES ('22594', '나이트 엘프 계획서', 'Plans des elfes de la nuit', 'Nachtelfenpläne', '暗夜精灵计划表', '夜精靈的計畫', 'Planes de los elfos de la noche', 'Planes de los elfos de la noche', 'Планы ночных эльфов', '샬란디스 섬에서 모은 계획서를 한군데 모아 놓은 두루마리입니다.', 'Tous les plans rassemblés sur l’île de Shalandis sont roulés ensemble.', 'Die vollständigen Pläne, die Ihr auf der Insel Shalandis zusammengetragen habt.', '从沙兰蒂斯岛上收集到的所有计划文件。', '所有從薩藍迪斯島來的文件都放在一起。', 'Todos los planes de la Isla Shalandis en un rollo.', 'Todos los planes de la Isla Shalandis en un rollo.', 'Все планы с острова Шаландис, одним свертком.', '15050');
