INSERT INTO `locales_item` VALUES ('23857', '산왕의 유산', 'L\'Héritage du roi de la montagne', 'Vermächtnis des Bergkönigs', '山丘之王的遗产', '山脈之王傳說', 'Legado del rey de la montaña', 'Legado del rey de la montaña', 'Право Горных королей', '이 책의 정수는 카라잔에 귀속되어 있습니다.', 'L\'essence de ce livre est liée à Karazhan.', 'Die Essenz dieses Buchs ist an Karazhan gebunden.', '这本书已经被卡拉赞的魔法绑定了。', '此書的精華與卡拉贊有關。', 'La esencia de este libro está vinculada a Karazhan.', 'La esencia de este libro está vinculada a Karazhan.', 'Информация, содержащаяся в этой книге, предназначена для Каражана.', '15050');
INSERT INTO `locales_item` VALUES ('23858', '그을린 책장', 'Page roussie', 'Angesengte Seite', '烧焦的书页', '燒焦的書頁', 'Página chamuscada', 'Página chamuscada', 'Обгорелая страница', '산왕의 유산에 있던 봉인을 파괴하고 남은 책장입니다.', 'Une seule page reste après avoir brisé le sceau de « L\'héritage du roi de la montagne ».', 'Nachdem das Siegel von \'Vermächtnis des Bergkönigs\' gebrochen wurde, verbleibt noch diese Seite.', '撕开《山丘之王的遗产》之后仅存的一页。', '在破壞\'山脈之王傳說\'的封印後僅存的一頁書頁。', 'Queda una página después de romper el sello de la \'Legado del Rey de la Montaña\'.', 'Queda una página después de romper el sello de la \'Legado del Rey de la Montaña\'.', 'После того как вы вскрыли печать на \"Праве Горных королей\", от книги остается всего одна страница.', '15050');
INSERT INTO `locales_item` VALUES ('23859', '나지부스 기념비 상형문자', 'Glyphe du monument de Nazzivus', 'Glyphe vom Monument der Nazzivus', '纳兹维安碑石雕文', '納茲維斯紀念雕紋', 'Monumento glifo de Nazzivus', 'Monumento glifo de Nazzivus', 'Иероглиф монумента Наззивуса', '사악하게 보이는 글자와 함께 이야기를 담고 있는 듯한 사람 형체의 기호들이 새겨져 있습니다.', 'Des caractères torturés accompagnent une série de silhouettes humanoïdes, et semblent raconter une sorte d\'histoire.', 'Finster aussehende Kreaturen in Begleitung einiger humanoider Gestalten bilden zusammen eine Art Erzählung.', '邪恶的字符旁画着一些人型生物，似乎这些文字是对图画的注解。', '看來邪惡的特徵伴隨著一系列類人的特性成為某種故事的一部分。', 'Varias figuras de aspecto humano junto a unos caracteres siniestros como en una especie de relato.', 'Varias figuras de aspecto humano junto a unos caracteres siniestros como en una especie de relato.', 'Рядом с изображением нескольких человекоподобных фигур начертаны зловещие символы. Кажется, они связаны какой-то историей.', '15050');
