INSERT INTO `locales_item` VALUES ('23995', '멀록 표시총', 'Marqueur de murlocs', 'Murlocsender', '鱼人标记枪', '魚人標示器', 'Marcador múrloc', 'Marcador múrloc', 'Маркировщик мурлоков', '멀록에게 꼬리표를 달 수 있습니다. 아프진 않을 것 같습니다.', 'Où es-tu, petit murloc? Ça ne fait pas mal…', 'Wo bist du, kleiner Murloc? Dies wird kein bisschen weh tun...', '小鱼人，你在哪里？这个一点都不疼……', '你在哪啊，小魚人?這一點都不痛喔……', '¿Dónde estás, murloquito lindo? No te va a doler...', '¿Dónde estás, murloquito lindo? No te va a doler...', 'Где ты, малыш-мурлок? Больно не будет...', '15050');
