INSERT INTO `locales_item` VALUES ('27479', '불타오르는 횃불', 'Torche enflammée', 'Flammende Fackel', '燃烧的火把', '燃焰火炬', 'Antorcha llameante', 'Antorcha llameante', 'Горящий факел', '살아 움직이는 듯한 불길이 연료에 흠뻑 적셔진 횃불 끝에서 불타고 있습니다.', 'Une flamme vive crépite à l’extrémité de la torche trempée dans la poix.', 'Flammen zucken am Ende einer mit Pech getränkten Fackel.', '熊熊的火焰在火把顶端燃烧。', '一束活躍的火焰於浸在樹脂中的火炬盡頭劈啪作響。', 'Una llama viva chisporrotea en la punta de una antorcha empapada de brea.', 'Una llama viva chisporrotea en la punta de una antorcha empapada de brea.', 'На конце факела, смоченном смолой, весело потрескивало пламя.', '15050');
