INSERT INTO `locales_item` VALUES ('27552', '부드러운 가죽 조끼', 'Gilet en cuir souple', 'Weiche Lederweste', '软皮外套', '柔軟的皮外衣', 'Jubón de cuero suave', 'Jubón de cuero suave', 'Мягкий кожаный жилет', '', '', '', '', '', '', '', '', '15050');
INSERT INTO `locales_item` VALUES ('27553', '붉은 황소 기력충전음료', 'Boisson énergétique du bœuf cramoisi', 'Purpurbull Energietrank', '赤牛能量饮料', '赤紅能量飲品', 'Bebida energética de buey carmesí', 'Bebida energética de buey carmesí', 'Багровый энергетический напиток', '상쾌한 아침을 위한 최적의 음료입니다.', 'Le remontant idéal pour les lendemains qui déchantent.', 'Der perfekte Muntermacher für den harten Morgen nach einer langen Nacht.', '通宵劳作之后的清晨仍能让我保持清醒的强劲饮料。', '對熬夜後的痛苦早晨而言是完美的興奮劑。', 'El perfecto reconstituyente para esas duras mañanas tras una noche agitada.', 'El perfecto reconstituyente para esas duras mañanas tras una noche agitada.', 'Прекрасно взбадривает тяжелым утром после бурной ночи', '15050');
