INSERT INTO `locales_item` VALUES ('28032', '섬세한 녹색 판초', 'Poncho délicat vert', 'Aparter grüner Poncho', '精致的绿色雨衣', '柔軟的綠斗篷', 'Poncho verde fino', 'Poncho verde fino', 'Изысканное зеленое пончо', '그들은 당신의 뒷모습만을 기억할 것입니다.', 'Ils ne vous verront pas arriver, mais ils vous verront certainement partir.', 'Sie werden nicht sehen, wenn Ihr kommt, aber ganz bestimmt, wenn Ihr geht.', '他们看不到你出现，但一定可以看到你离开。', '他們不會看見你進來，但他們絕對會看到你離開。', 'No te verán llegar pero desde luego te verán al marcharte.', 'No te verán llegar pero desde luego te verán al marcharte.', 'Они не заметят как вы придете, но ваш уход им запомнится надолго.', '15050');
