INSERT INTO `locales_item` VALUES ('30402', '현장 요원의 팔보호구', 'Brassards d\'agent de terrain', 'Armschienen des Außenagenten', '特派员的护腕', '戰場密探護腕', 'Brazales de agente de campo', 'Brazales de agente de campo', 'Наручи полевого агента', '안쪽 표면엔 B.O.O.M. 이란 글자가 새겨져 있습니다.', 'Leur intérieur porte l\'inscription : B.O.U.M.', 'Die Inschrift B.U.M.M. ziert die Innenseite.', '内面上刻有“爆裂推进式多缸火箭航天局”的字样。', '內側的平面刻有B.O.O.M.這個名字。', 'En la parte interior figura la inscripción B.U.M.', 'En la parte interior figura la inscripción B.U.M.', 'На внутренней стороне написано: \"МОЗГ\".', '15050');
