INSERT INTO `locales_item` VALUES ('32685', '오그릴라 닭발 튀김', 'Doigts de poulet d\'Ogri\'la', 'Halbes Hähnchen von Ogri\'la', '奥格瑞拉鸡翅', '歐格利拉雞柳條', 'Palitos de pollo de Ogri\'la', 'Palitos de pollo de Ogri\'la', 'Цыплячьи крылышки из Огри\'лы', '이건 닭발이라고 보기엔 너무 큽니다. 크기가 타우렌 허벅지만 하네요!', 'En fait, c\'est plutôt un bras.', 'Wohl eher ein ganzes als ein halbes.', '美味的鸡翅。', '一塊雞柳條比一整隻手臂小一點而已。', 'Más vale palito en mano que cientos volando.', 'Más vale palito en mano que cientos volando.', 'Это даже не крылышки, а целые крылья!', '15050');
INSERT INTO `locales_item` VALUES ('32686', '행운이 깃든 밍고의 내장', 'Entrailles divinatoires de Mingo', 'Mingos Glücksinnereien', '米葛的塔罗牌美餐', '敏格的詩籤肉雜', 'Menudillos de la fortuna de Mingo', 'Menudillos de la fortuna de Mingo', 'Потрошки удачи Минго', '안에 담긴 점괘를 찾아보세요. 오그릴라의 지혜를 음미하시거나 자신의 운명에 대해 배워보세요.', 'Lisez votre avenir dans les entrailles ! Délectez-vous de la sagesse d\'Ogri\'la, gagnez un prix, ou apprenez quel sera votre destin !', 'Findet Euer Glück im Inneren! Labt Euch an der Weisheit von Ogri\'la, gewinnt einen Preis oder erfahrt etwas über Euer Schicksal!', '寻找属于你的塔罗牌！感受奥格瑞拉的智慧，赢取你的奖品，或者了解你的命运！', '在其中找出屬於你的詩籤!沐浴在歐格利拉的智慧中，贏得一份獎賞，或者是得知你的命運!', '¡Encuentra tu fortuna dentro! ¡Disfruta de la sabiduría de Ogri\'la, gana un premio o entérate de lo que te depara el destino!', '¡Encuentra tu fortuna dentro! ¡Disfruta de la sabiduría de Ogri\'la, gana un premio o entérate de lo que te depara el destino!', 'Прикоснись к тайне! Познай мудрость Огри\'лы, выиграй приз либо пролей свет на свою будущую судьбу!', '15050');
