INSERT INTO `locales_item` VALUES ('43128', '포도주 단지', 'Cruche de vin', 'Krug Wein', '一壶葡萄酒', '一壺葡萄酒', 'Jarra de vino', 'Jarra de vino', 'Кувшин с вином', '커다란 단지에 담긴 포도주보다 더 좋은 건 없습니다.', 'Il n\'y a rien de mieux que du vin dans une cruche de quatre litres.', 'Gibt nichts Besseres als einen Krug, gefüllt mit einem Liter Wein.', '没有什么比满满一壶葡萄酒更棒的了。', '沒有比一加侖葡萄酒更棒的了。', 'Nada mejor que vino en una gran jarra de cinco litros.', 'Nada mejor que vino en una gran jarra de cinco litros.', 'Всего лишь кувшин вина объемом с галлон.', '15050');
