INSERT INTO `locales_item` VALUES ('43138', '반쯤 찬 달라란 포도주 잔', 'Verre de vin à moitié plein', 'Halbvolles Dalaranweinglas', '半满的达拉然酒杯', '半滿的達拉然葡萄酒杯', 'Copa de vino de Dalaran medio llena', 'Copa de vino de Dalaran medio llena', 'Полупустой бокал с даларанским вином', '', '', '', '', '', '', '', '', '15050');
INSERT INTO `locales_item` VALUES ('43139', '빈 치즈 접시', 'Plateau à fromages', 'Leere Käseplatte', '空的奶酪盘', '空的起司盤', 'Fuente para servir queso vacía', 'Fuente para servir queso vacía', 'Пустая сырная тарелка', '실제로 예전에는 낡은 방패였지만, 라니드가 눈치채지는 못할 것 같습니다.', 'En fait, c\'est un vieux bouclier, mais Ranid ne s\'en rendra sûrement pas compte.', 'Eigentlich ist es ein alter Schild, doch Ranid wird es wahrscheinlich nicht bemerken.', '实际上这是一面旧盾牌，但是兰尼德多半不会注意到。', '這其實是面老舊的盾牌，但拉尼德大概不會注意到。', 'En realidad es un escudo viejo pero, probablemente, Ranid no lo advertirá.', 'En realidad es un escudo viejo pero, probablemente, Ranid no lo advertirá.', 'Вообще-то это старый щит, но Ранид, скорее всего, не заметит разницы.', '15050');
