INSERT INTO `locales_item` VALUES ('43620', '불순물 섞인 주문 강화의 비약', 'Elixir de puissance des sorts cassé', 'Zerbrochene Phiole Zaubermachtelixier', '破损的法术能量药剂', '破損的法術能量藥劑', 'Elixir de poder con hechizos roto', 'Elixir de poder con hechizos roto', 'Разбавленный эликсир силы заклинаний', '', '', '', '', '', '', '', '', '15050');
INSERT INTO `locales_item` VALUES ('43621', '불순물 섞인 노겐포저의 비약', 'Elixir Brouillecaboche cassé', 'Zerbrochene Phiole Noggenfoggers Elixier', '破损的诺格弗格药剂', '破損的諾格弗格藥劑', 'Elixir de Tragonublo roto', 'Elixir de Tragonublo roto', 'Разбавленный эликсир Гогельмогеля', '', '', '', '', '', '', '', '', '15050');
