INSERT INTO `locales_item` VALUES ('44468', '흠뻑 젖은 편지', 'Lettre trempée', 'Wassergetränkter Brief', '浸水的信件', '浸水的信件', 'Carta empapada de agua', 'Carta empapada de agua', 'Вымокшее письмо', '물에 젖어 읽기가 매우 어렵습니다.', 'L\'eau a provoqué des dégâts qui rendent la lettre quasiment illisible.', 'Durch das Wasser wird dieser Brief sehr schwer zu lesen sein.', '在水中泡了太久，这封信恐怕非常难以辨认了。', '水漬讓這封信非常難以閱讀。', 'El agua ha dañado la carta y es casi imposible leerla.', 'El agua ha dañado la carta y es casi imposible leerla.', 'Повреждено водой так, что его почти невозможно прочитать.', '15050');
