INSERT INTO `locales_item` VALUES ('50161', '정찬복 상자', 'Boîte d\'habit de soirée', 'Karton \'Abendanzug\'', '晚宴礼服箱', '晚宴套裝盒', 'Caja de traje de noche', 'Caja de traje de noche', 'Коробка с вечерним костюмом', '아름다운 정찬복 세 가지 중 하나가 담겨 있습니다.', 'Contient l\'un des trois habits de soirée ravissants.', 'Enthält einen von drei Abendanzügen.', '装有三种可爱的晚宴礼服中的一件。', '裝有三種可愛的晚宴套裝的其中一件。', 'Contiene uno de los tres trajes de noche preciosos.', 'Contiene uno de los tres trajes de noche preciosos.', 'Внутри лежит один из трех костюмов чудесной расцветки.', '15050');
INSERT INTO `locales_item` VALUES ('50163', '아름다운 장미', 'Rose ravissante', 'Wunderschöne Rose', '娇艳的玫瑰', '可愛的玫瑰', 'Rosa preciosa', 'Rosa preciosa', 'Прекрасная роза', '오래가지는 않더라도, 아름다운 꽃입니다.', 'Elle ne durera pas longtemps, mais elle est ravissante.', 'Sie wird sich nicht lang halten, aber sie ist wunderschön.', '红颜易老，真爱永留。', '雖然並不長久，但可愛而美好。', 'No durará mucho, pero es preciosa.', 'No durará mucho, pero es preciosa.', 'Она просто чудесна! Хотя, возможно, быстро завянет…', '15050');
