INSERT INTO `locales_item` VALUES ('51320', '은빛 성기사단의 표장', 'Ecusson de la Main d\'argent', 'Abzeichen der Silbernen Hand', '白银之手骑士团徽章', '白銀之手的徽章', 'Distintivo de la Mano de Plata', 'Distintivo de la Mano de Plata', 'Знак Серебряной Длани', '은빛 성기사단으로 받아들여질 때 얻는 표장.', 'Une médaille reçue lorsque l\'on est intronisé chevalier de la Main d\'argent.', 'Eine Ehrenmedaille, die bei der Aufnahme in die Ränge der Ritter der Silbernen Hand verliehen wird.', '白银之手骑士团的入伍徽章。', '受到白銀之手騎士團認可而加入時所頒發的勳章。', 'Una medalla que se otorga a los nuevos caballeros de la Mano de Plata.', 'Una medalla que se otorga a los nuevos caballeros de la Mano de Plata.', 'Медаль, выдаваемая при вступлении в ряды рыцарей Серебряной Длани.', '15050');
